// Match entrances and whistles are explicit pauses; no elapsed match time is skipped.
var matchCeremonyHold=false,ceremonyPending=null,ceremonyMatch=null,ceremonyTimer=0;
const ceremonyDialog=document.createElement('dialog');ceremonyDialog.id='match-ceremony';ceremonyDialog.setAttribute('aria-labelledby','match-ceremony-title');document.body.append(ceremonyDialog);
function closeCeremony(){clearTimeout(ceremonyTimer);ceremonyDialog.close();matchCeremonyHold=false;matchClock.reset();movementStamp=performance.now();$('primary')?.focus({preventScroll:true});}
ceremonyDialog.addEventListener('cancel',event=>{event.preventDefault();closeCeremony();});
function showMatchCeremony(kind){
 if(!state||view!=='match')return;const match=state;ceremonyMatch=match;matchCeremonyHold=true;matchClock.reset();
 const pre=kind==='preview',half=kind==='half',full=kind==='full',d=pre?Opposition.read(season):null;
 const title=pre?'오늘의 상대를 확인하세요':half?'전반 종료':full?'경기 종료':'킥오프';
 const esc=escapeText,score=esc(S.club(S.own).short)+' '+state.score.join(' : ')+' '+esc(S.opponentFor(season).short);
 const summary=pre&&d.valid?'<h3>'+esc(d.club.name)+'</h3><dl class="ceremony-facts"><div><dt>포메이션</dt><dd>'+esc(d.plan.formation.split('').join('–'))+'</dd></div><div><dt>전술 성향</dt><dd>'+esc(d.plan.label)+'</dd></div><div><dt>선발 종합 · 계산</dt><dd>'+Math.round(d.lineup.reduce((n,p)=>n+p.overall,0)/d.lineup.length)+'</dd></div><div><dt>평균 체력</dt><dd>'+Math.round(d.condition.opponent)+'</dd></div></dl><p><b>요주의 선수</b> '+esc(d.keyPlayer?.name||'선발 전원')+'</p><p>'+esc(d.advice)+'</p>':'<strong class="ceremony-score">'+score+'</strong><p>'+(half?'선수들의 체력과 전반 흐름을 확인하고 후반을 준비하세요.':full?'추가시간까지 끝났습니다. 기록을 확인한 뒤 결과를 확정해 주세요.':'관중의 함성 속에서 경기가 시작됩니다.')+'</p>';
 ceremonyDialog.innerHTML='<div class="ceremony-content"><small>'+esc(season.competition==='cup'?'국내컵':season.competition==='europe'?'유럽 대회':S.divisionInfo(season.league.division).name||'리그')+' · '+(pre?'경기 전 브리핑':F.clockLabel(state)+'′')+'</small><h2 id="match-ceremony-title">'+title+'</h2>'+summary+'<div class="ceremony-actions">'+(pre?'<button id="ceremony-lineup">상대 선발 자세히</button><button id="ceremony-ready" class="primary">상대 확인 · 킥오프</button>':'<button id="ceremony-ready" class="primary">'+(half?'라커룸으로':full?'경기 기록 보기':'경기 보기')+'</button>')+'</div></div>';
 if(!ceremonyDialog.open)ceremonyDialog.showModal();ceremonyDialog.dataset.kind=kind;$('ceremony-ready').focus({preventScroll:true});
 $('ceremony-ready').onclick=()=>{if(state!==match)return closeCeremony();closeCeremony();if(pre){F.enableStoppage(state);const from=state.logs.length;F.begin(state);presentMatchEvents(state.logs.slice(from),true);save();render();showMatchCeremony('kickoff');ceremonyTimer=setTimeout(()=>{if(ceremonyDialog.open&&ceremonyMatch===match&&ceremonyDialog.dataset.kind==='kickoff')closeCeremony();},motionEnabled()?1800:400);}else if(half)openMatchPopup('talk');else if(full)openMatchPopup('stats');};
 if(pre)$('ceremony-lineup').onclick=()=>{closeCeremony();openMatchPopup('opponent');};
}
const ceremonyAdvance=advanceMatchWithFeedback;advanceMatchWithFeedback=function(){if(ceremonyDialog.open)return;if(state?.phase==='prep'){showMatchCeremony('preview');return;}if(typeof pendingVisibleMatchEvent==='function'&&pendingVisibleMatchEvent())return;if(ceremonyPending&&ceremonyPending.match===state&&ceremonyPending.phase===state.phase){const phase=ceremonyPending.phase;ceremonyPending=null;showMatchCeremony(phase);return;}const half=state?.phase==='half';ceremonyAdvance();if(half){showMatchCeremony('kickoff');ceremonyTimer=setTimeout(closeCeremony,motionEnabled()?1400:400);}};
const ceremonyEvents=presentMatchEvents;presentMatchEvents=function(events,fast=false){ceremonyEvents(events,fast);if(['half','full'].includes(state?.phase)&&events.some(e=>e.type==='break'))ceremonyPending={match:state,phase:state.phase};};
setInterval(()=>{if(!ceremonyPending||view!=='match'||document.hidden||document.querySelector('dialog[open]'))return;if(state!==ceremonyPending.match||state.phase!==ceremonyPending.phase){ceremonyPending=null;return;}if(motionEnabled()&&movementHighlightPending())return;const phase=ceremonyPending.phase;ceremonyPending=null;showMatchCeremony(phase);},100);
const ceremonyRender=render;render=function(){ceremonyRender();if(!state||view!=='match')return;const a=state.stoppage,lim=F.clockLimits(state);if(a&&F.running(state)&&(state.phase==='first'&&state.minute>=45||state.phase==='third'&&state.minute>=lim.regulation)){$('phase-label').textContent=(state.phase==='first'?'전반':'후반')+' 추가시간 +'+(state.phase==='first'?a.first:a.second)+'분';}};
